import { useContext, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { AuthContext } from "../context/AuthContext";
import { ComplaintContext } from "../context/ComplaintContext";
import "../styles/global.css";

function Navbar() {
  const { logout } = useContext(AuthContext);
  const { complaints } = useContext(ComplaintContext);
  const navigate = useNavigate();

  const [showNotif, setShowNotif] = useState(false);

  // ⭐ unread = pending complaints
  const unread = complaints.filter(c => c.status === "Pending").length;

  return (
    <div className="nav">
      <div
        className="logo"
        onClick={() => navigate("/")}
        style={{ cursor: "pointer" }}
      >
        Citizen Voice
      </div>

      <div className="nav-links">
        {/* HOME */}
        <span onClick={() => navigate("/")} className="nav-item">
          Home
        </span>

        {/* ADD → MAIN PAGE (Dashboard) */}
        <span onClick={() => navigate("/")} className="nav-item">
          Add
        </span>

        {/* TRACK */}
        <span onClick={() => navigate("/track")} className="nav-item">
          Track
        </span>

        {/* 🔔 BELL */}
        <div className="bell" onClick={() => setShowNotif(!showNotif)}>
          🔔
          {unread > 0 && <span className="bell-badge">{unread}</span>}
        </div>

        {/* 🔔 POPUP */}
        {showNotif && (
          <div className="notif-popup">
            <h4>Notifications</h4>

            {complaints.length === 0 ? (
              <p>No notifications</p>
            ) : (
              complaints.map((c, i) => (
                <div key={i} className="notif-item">
                  📌 {c.department} - {c.status}
                </div>
              ))
            )}
          </div>
        )}

        {/* LOGOUT */}
        <button className="logout" onClick={logout}>
          Logout
        </button>
      </div>
    </div>
  );
}

export default Navbar;
